private open class BoxApiPigeonCodec : StandardMessageCodec() {
  override fun readValueOfType(type: Byte, buffer: ByteBuffer): Any? {
    return when (type) {
      129.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          StartRequest.fromList(it)
        }
      }
      130.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          ConfigOptions.fromList(it)
        }
      }
      131.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          SelectOutboundRequest.fromList(it)
        }
      }
      132.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          KernelFailureMsg.fromList(it)
        }
      }
      133.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          KernelSnapshotMsg.fromList(it)
        }
      }
      134.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          LaunchSpecMsg.fromList(it)
        }
      }
      135.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          DesiredRequestMsg.fromList(it)
        }
      }
      136.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          ReceiptMsg.fromList(it)
        }
      }
      137.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          ValidateConfigRequest.fromList(it)
        }
      }
      138.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          ValidateConfigResult.fromList(it)
        }
      }
      139.toByte() -> {
        return (readValue(buffer) as? List<Any?>)?.let {
          InstalledApp.fromList(it)
        }
      }
      else -> super.readValueOfType(type, buffer)
    }
  }
  override fun writeValue(stream: ByteArrayOutputStream, value: Any?)   {
    when (value) {
      is StartRequest -> {
        stream.write(129)
        writeValue(stream, value.toList())
      }
      is ConfigOptions -> {
        stream.write(130)
        writeValue(stream, value.toList())
      }
      is SelectOutboundRequest -> {
        stream.write(131)
        writeValue(stream, value.toList())
      }
      is KernelFailureMsg -> {
        stream.write(132)
        writeValue(stream, value.toList())
      }
      is KernelSnapshotMsg -> {
        stream.write(133)
        writeValue(stream, value.toList())
      }
      is LaunchSpecMsg -> {
        stream.write(134)
        writeValue(stream, value.toList())
      }
      is DesiredRequestMsg -> {
        stream.write(135)
        writeValue(stream, value.toList())
      }
      is ReceiptMsg -> {
        stream.write(136)
        writeValue(stream, value.toList())
      }
      is ValidateConfigRequest -> {
        stream.write(137)
        writeValue(stream, value.toList())
      }
      is ValidateConfigResult -> {
        stream.write(138)
        writeValue(stream, value.toList())
      }
      is InstalledApp -> {
        stream.write(139)
        writeValue(stream, value.toList())
      }
      else -> super.writeValue(stream, value)
    }
  }
}


